<template><div class="app-container"><el-table v-loading="loading" :data="list"><el-table-column prop="roleId" label="角色ID" width="80" /><el-table-column prop="roleName" label="角色名称" /><el-table-column prop="roleKey" label="角色标识" /><el-table-column prop="status" label="状态" width="80"><template #default="scope"><el-tag :type="scope.row.status==='0'?'success':'danger'">{{scope.row.status==='0'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="scope"><el-button link type="primary" icon="Edit">编辑</el-button><el-button link type="primary" icon="Delete">删除</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="queryParams.pageNum" v-model:limit="queryParams.pageSize" @pagination="getList" /></div></template>
<script setup lang="ts">import { ref, reactive, onMounted } from 'vue';import request from '@/utils/request';const loading=ref(false), total=ref(0), list=ref<any[]>([]);const queryParams=reactive({pageNum:1,pageSize:10});const getList=async()=>{loading.value=true;try{const res=await request({url:'/system/role/list',method:'get',params:queryParams});list.value=res.rows;total.value=res.total}finally{loading.value=false}};onMounted(getList)</script>
